        # Expected parsing exceptions
        pass
    except Exception as e:
        # Unexpected crashes
        raise e

def main():
    atheris.instrument_all()
    atheris.Setup(sys.argv, TestOneInput)
    atheris.Fuzz()

if __name__ == "__main__":
    main()

